//! The app mark: a violet rounded square with an open book whose pages turn into sound waves (same drawing as the
//! PWA icons generated by `tools/make_icons.py`).

use leptos::prelude::*;

#[component]
pub fn Logo(#[prop(optional)] large: bool) -> impl IntoView {
    view! {
        <svg class="logo" class:logo--large=large viewBox="0 0 64 64" aria-hidden="true" focusable="false">
            <rect width="64" height="64" rx="16" fill="#7C6CFF" />
            <path
                d="M14 22c6-2.6 12-2.6 18 1.2c6-3.8 12-3.8 18-1.2v21c-6-2.6-12-2.6-18 1.2c-6-3.8-12-3.8-18-1.2z"
                fill="none"
                stroke="#fff"
                stroke-width="3.2"
                stroke-linejoin="round"
            />
            <path d="M32 23.2v21" stroke="#fff" stroke-width="3.2" stroke-linecap="round" />
            <path d="M20 31v6M25 28.5v11M39 28.5v11M44 31v6" stroke="#fff" stroke-width="2.6" stroke-linecap="round" opacity=".9" />
        </svg>
    }
}
